/* Task 6: window-scale keyboard controls. nextWholeScale/prevWholeScale
 * are pure step math (pinned by test_window_scale_helpers);
 * setWindowScale clamps to [0.25, 8] and resizes the window. */

static float g_windowScale = 1.0f;


float nextWholeScale(float s) {
	float n = floorf(s) + 1.0f;
	if(n < 0.25f) n = 0.25f;
	return n;
}


float prevWholeScale(float s) {
	float n = ceilf(s) - 1.0f;
	if(n < 0.25f) n = 0.25f;
	return n;
}


float getWindowScale(void) { return g_windowScale; }


void setWindowScale(float scale) {
	if(scale < 0.25f) scale = 0.25f;
	if(scale > 8.0f) scale = 8.0f;
	g_windowScale = scale;
	SetWindowSize((int)roundf(SCREEN_W * scale), (int)roundf(SCREEN_H * scale));
}


void presentFrame(RenderTexture2D gfx) {
	BeginDrawing();
	ClearBackground(BLACK);
	int sw = GetScreenWidth();
	int sh = GetScreenHeight();
	float s = fminf((float)sw / SCREEN_W, (float)sh / SCREEN_H);
	int dw = (int)(SCREEN_W * s);
	int dh = (int)(SCREEN_H * s);
	DrawTexturePro(gfx.texture, (Rectangle){ 0, 0, SCREEN_W, -SCREEN_H },
	               (Rectangle){ (sw - dw) / 2, (sh - dh) / 2, dw, dh },
	               (Vector2){ 0, 0 }, 0.0f, WHITE);
	EndDrawing();
}


void InitGUI(void) {
	const int screenWidth = SCREEN_W;
	const int screenHeight = SCREEN_H;

	if(!gThemeLoaded) {
		initDefaultColourScheme(&cs);
	}

	/* Fall back to hardcoded defaults if main() never set gFontConfig.
	 * The harness boots directly into InitGUI without going through the
	 * cfg/theme loader path, so it relies on these fallbacks. */
	if(gFontConfig.path[0] == '\0') {
		strncpy(gFontConfig.path, "resources/fonts/console.ttf", sizeof(gFontConfig.path) - 1);
		gFontConfig.path[sizeof(gFontConfig.path) - 1] = '\0';
		gFontConfig.size = 9;
		gFontConfig.spacing = 0;
	}

	SetConfigFlags(FLAG_WINDOW_RESIZABLE);
	InitWindow(screenWidth, screenHeight, "Spectrax");
	textFont = LoadFont("resources/fonts/setback.png");
	pixelFont = LoadFontEx(gFontConfig.path, gFontConfig.size, NULL, 255);
	/* Phase B (mixed fonts): values are drawn in a monospace face so
	 * digits are tabular — a proportional face makes a changing value
	 * (the modulation pass rewrites them every block) shift sideways. */
	monoFont = LoadFontEx("resources/fonts/console.ttf", gFontConfig.size, NULL, 255);
	initCustomFont(&symbolFont, "resources/fonts/iconzfin.png", 8, 10, 12);
	Image dialimg = LoadImage("resources/images/dial2.png");
	dial = LoadTextureFromImage(dialimg);
	UnloadImage(dialimg);
	curveIconsTexture = buildCurveIconTexture();
	SetTargetFPS(60);
}


void drawRotatedDial(int x, int y, int w, int h, int radius, int startAngle, int offsetAngle) {
	DrawCircleSector((Vector2){ x + radius, y + radius }, radius + 2, startAngle, startAngle + offsetAngle, 32, cs.dial);
	DrawTexturePro(dial, (Rectangle){ 0, 0, 48, 48 }, (Rectangle){ x + radius, y + radius, w, h }, (Vector2){ radius, radius }, startAngle + offsetAngle, WHITE);
}


void drawValueDisplay(int x, int y, int w, int h, char *text, Color textColour, int fontSize) {
	drawValueDisplayFont(&pixelFont, x, y, w, h, text, textColour, fontSize);
}

/* Phase B: same plate, explicit face — dial values pass the style's
 * font so a `"font": "mono"` value renders in the monospace face. */
void drawValueDisplayFont(Font *f, int x, int y, int w, int h, char *text, Color textColour, int fontSize) {
	DrawRectangle(x, y, w, h, cs.valueDisplayBg);
	float sz = (float)(fontSize > 0 ? fontSize : 9);
	/* Vertically centre inside the plate so a taller plate (2x) does not
	 * leave the digits riding at the top edge. */
	float th = (float)fontSize;
	float ty = (float)y + ((float)h - th) * 0.5f;
	DrawTextEx(*f, text, (Vector2){ (float)x + 4, ty }, sz, 1, textColour);
}


/* Colour-aware panel (shadow + fill + border). A highlighted panel uses
 * borderColourSelected when the style supplied one (alpha != 0);
 * otherwise it keeps the legacy theme highlight so unset styles look
 * exactly as before. */
void drawPanelRect(int x, int y, int w, int h, float line_w, bool highlighted,
                   Color borderColour, Color borderColourSelected) {
	int o = (int)line_w;
	Color shadowColour = highlighted ? (Color){ 0, 0, 0, 200 } : (Color){ 0, 0, 0, 140 };
	DrawRectangle(x + o, y + o, w, h, shadowColour);
	DrawRectangle(x, y, w, h, cs.panel);
	Color outline = borderColour;
	if(highlighted) {
		outline = (borderColourSelected.a != 0) ? borderColourSelected : cs.highlightedCell;
	}
	DrawRectangleLinesEx((Rectangle){ x, y, w, h }, line_w, outline);
}


/* Map a style's fontName (text/symbol/pixel) to the corresponding Font
 * global. The two named fonts come from the GUI init; everything else
 * (including the empty string) falls back to pixelFont. */
Font *styleFont(const char *name) {
	extern Font textFont;
	extern Font symbolFont;
	if(name && strcmp(name, "text") == 0) {
		return &textFont;
	}
	if(name && strcmp(name, "symbol") == 0) {
		return &symbolFont;
	}
	if(name && strcmp(name, "mono") == 0) {
		return &monoFont;
	}
	return &pixelFont;
}


/* The dial's two rings. Computes the base angle (which the needle
 * rotates by, returned through angleOut) and paints:
 *   - the modulation sector, startAngle -> effective value, dim;
 *   - the base sector, startAngle -> base value, bright, over it.
 * Unmodulated the two angles coincide and the dim ring is covered
 * entirely, so no branch is needed beyond "is there a modulator".
 * Display-only: getParameterValue is a read the audio thread also makes. */
static void drawDialArcs(const GuiNode *gn, const DialStyle *st, const DialGeometry *g, float *angleOut) {
	float baseAngle = 0.0f;
	float modAngle = 0.0f;
	dialArcAngles(gn->p, (float)st->knob.sweep, &baseAngle, &modAngle);
	Vector2 centre = { g->knobX + (float)st->knob.radius, g->knobY + (float)st->knob.radius };
	/* A ring, not a pie: the knob graphic is opaque and covers a pie's
	 * interior, so only the band outside its edge reads. */
	float rIn = (float)st->knob.radius - 2.0f;
	float rOut = (float)st->knob.radius + 3.0f;
	float start = (float)st->knob.startAngle;
	if(gn->p->modulators && modAngle != baseAngle) {
		Color dim = st->knob.modColor;
		if(dim.a == 0) {
			/* A style that never set modColor still gets a visible
			 * second ring: the dial's own colour at 45%. */
			dim = st->knob.color;
			dim.a = (unsigned char)((float)dim.a * 0.45f);
		}
		DrawRing(centre, rIn, rOut, start, start + modAngle, 48, dim);
	}
	DrawRing(centre, rIn, rOut, start, start + baseAngle, 48, st->knob.color);
	if(angleOut) {
		*angleOut = baseAngle;
	}
}

void drawDialGuiNode(void *self) {
	GuiNode *gn = (GuiNode *)self;
	if(!gn->p) {
		return;
	}
	const DialStyle *st = resolveDialStyle(gn);
	char paramValue[50];
	snprintf(paramValue, 50, st->value.format, gn->p->baseValue);
	DialGeometry g;
	computeDialGeometry(gn, st, &g);
	/* The graphic can be drawn smaller than its cell: the value and
	 * modulation rings live in the band between graphic and radius. */
	int graphic = st->knob.graphicSize > 0 ? st->knob.graphicSize : st->knob.size;
	if(graphic != st->knob.size && st->knob.size > 0) {
		float k = (float)graphic / (float)st->knob.size;
		g.knobW = (int)((float)g.knobW * k);
		g.knobH = (int)((float)g.knobH * k);
	}

	float angle = 0.0f;
	drawPanelRect(gn->x, gn->y, gn->w, gn->h, st->border.borderWidth, gn->selected,
	               st->border.color, st->border.colorSelected);
	/* The value ring, then the modulation ring behind it, then the knob
	 * graphic inside both. The ring used to be skipped whenever the style
	 * named a knob asset, which left the shipped dial with no value
	 * indication at all. */
	drawDialArcs(gn, st, &g, &angle);
	if(st->knob.hasAsset && st->knob.assetTex.id != 0) {
		DrawTexturePro(st->knob.assetTex, (Rectangle){ 0, 0, st->knob.assetTex.width, st->knob.assetTex.height },
		               (Rectangle){ g.knobX + st->knob.radius + st->knob.offsetX, g.knobY + st->knob.radius + st->knob.offsetY, g.knobW, g.knobH },
		               (Vector2){ g.knobW / 2.0f, g.knobH / 2.0f }, st->knob.startAngle + angle, WHITE);
	} else {
		/* DrawTexturePro places the rotated quad's centre at
		 * (dest.x, dest.y), not at (dest + origin) — so the dest
		 * top-left must carry the +radius offset for the knob graphic
		 * to sit over the arc. knob.offsetX/offsetY nudge it further. */
		DrawTexturePro(dial, (Rectangle){ 0, 0, 48, 48 },
		               (Rectangle){ g.knobX + st->knob.radius + st->knob.offsetX, g.knobY + st->knob.radius + st->knob.offsetY, g.knobW, g.knobH },
		               (Vector2){ st->knob.radius, st->knob.radius }, st->knob.startAngle + angle, WHITE);
	}
	const CurveIconStyle *ci = &st->curveIcon;
	if(ci->frameCount > 0) {
		int idx = curveIconIndex(gn->p->baseValue);
		if(idx < 0) {
			idx = 0;
		}
		if(idx >= ci->frameCount) {
			idx = ci->frameCount - 1;
		}
		/* The icon replaces the dial's value/numeric and is centred on
		 * the knob; offsetX/offsetY nudge it from that centre. */
		float iconX = g.knobX + (g.knobW - (float)ci->size) * 0.5f + (float)ci->offsetX;
		float iconY = g.knobY + (g.knobH - (float)ci->size) * 0.5f + (float)ci->offsetY;
		DrawTexturePro(curveIconsTexture,
		               (Rectangle){ idx * (float)CURVE_ICON_SIZE, 0, (float)CURVE_ICON_SIZE, (float)CURVE_ICON_SIZE },
		               (Rectangle){ iconX, iconY, (float)ci->size, (float)ci->size },
		               (Vector2){ 0, 0 }, 0.0f, ci->color);
	} else if(g.valueW > 0 && g.valueH > 0) {
		drawValueDisplayFont(styleFont(st->value.fontName), g.valueX, g.valueY, g.valueW, g.valueH,
		                     paramValue, st->value.color, st->value.fontSize);
	}
	if(st->label.fontSize > 0) {
		Font *lf = styleFont(st->label.fontName);
		/* labelX is the label's centre (cell-centred caption); centre the
		 * text on it. */
		float lw = MeasureTextEx(*lf, gn->name, st->label.fontSize, st->label.spacing).x;
		DrawTextEx(*lf, gn->name, (Vector2){ g.labelX - lw * 0.5f, g.labelY }, st->label.fontSize, st->label.spacing,
		           gn->selected ? st->label.colorSelected : st->label.color);
	}
}


/* Spec #2: return the Vector2 where a dial's name label should be drawn,
 * offset from the node's padded origin. drawDialGuiNode uses (offX=-28,
 * offY=+18); drawDiscreteDialGuiNode uses (offX=+6, offY=+21). Centralised
 * so the picker overlay (which draws the selected dial's label twice, once
 * at the source row and once at the destination cell) can position its
 * duplicate label exactly where the dial drew it. */
Vector2 dialLabelPos(const GuiNode *gn, int offX, int offY) {
	int tmpx = gn->x + gn->padding + 2;
	int tmpy = gn->y + gn->padding;
	return (Vector2){ (float)(tmpx + offX), (float)(tmpy + offY) };
}


GuiNode *createDialGuiNode(int x, int y, int w, int h, int padding, NodeAlignment na, const char *name, bool selected, OnPressCallback cb, Parameter *p) {
	GuiNode *gn = createGuiNode(x, y, w, h, padding, na, name, 1, selected);
	if(gn == NULL) {
		printf("createDialGuiNode error, could not create.");
		return NULL;
	}
	gn->callback = cb;
	gn->p = p;
	gn->drawable = true;
	gn->draw = drawDialGuiNode;
	return gn;
}


GuiNode *createActionBtnGuiNode(int x, int y, int w, int h, int padding, NodeAlignment na, const char *name, bool selected, ActionCallback cb, void *ctx) {
	GuiNode *gn = createGuiNode(x, y, w, h, padding, na, name, 1, selected);
	if(gn == NULL) {
		printf("createActionBtnGuiNode error, could not create.");
		return NULL;
	}
	gn->actionCb = cb;
	gn->actionCtx = ctx;
	gn->drawable = true;
	gn->draw = drawActionBtnGuiNode;
	return gn;
}


void drawActionBtnGuiNode(void *self) {
	GuiNode *gn = (GuiNode *)self;
	const BtnStyle *st = resolveBtnStyle(gn);
	drawPanelRect(gn->x, gn->y, gn->w, gn->h, st->border.borderWidth, gn->selected,
	               st->border.color, st->border.colorSelected);
	Font *lf = styleFont(st->label.fontName);
	const char *label = gn->text ? gn->text : gn->name;
	DrawTextEx(*lf, label,
	           (Vector2){ gn->x + gn->padding + st->label.offsetX, gn->y + gn->padding + st->label.offsetY },
	           st->label.fontSize, st->label.spacing,
	           gn->selected ? st->label.colorSelected : st->label.color);
	if(st->sublabel.fontSize > 0 && gn->sublabel) {
		Font *sf = styleFont(st->sublabel.fontName);
		Vector2 m = MeasureTextEx(*sf, gn->sublabel, (float)st->sublabel.fontSize, (float)st->sublabel.spacing);
		float sx = (float)gn->x + ((float)gn->w - m.x) * 0.5f;
		float sy = (float)gn->y + st->sublabel.offsetY;
		DrawTextEx(*sf, gn->sublabel, (Vector2){ sx, sy },
		           (float)st->sublabel.fontSize, (float)st->sublabel.spacing,
		           gn->selected ? st->sublabel.colorSelected : st->sublabel.color);
	}
}

/* Spec #1: route-picker destination cell. Replaces the standard action
 * button draw: no fill, no label, just an osc-orange/gold outline so the
 * picking grid reads as a uniform array of empty slots while the
 * highlighted-label overlay draws the focused cell's name on top. The
 * selected slot uses the same colour scheme as the highlighted label so
 * the two read as a single visual unit; outline thickness scales with
 * the cell so 31px and 35px dial cells both get a chunky 2px ring. */
void drawRouteDestGuiNode(void *self) {
	GuiNode *gn = (GuiNode *)self;
	const DestStyle *st = resolveDestStyle(gn);
	Color outline = gn->selected ? st->border.colorSelected : st->border.color;
	DrawRectangleLinesEx((Rectangle){ gn->x, gn->y, gn->w, gn->h },
	                     st->border.borderWidth, outline);
}

/* Task 3 (UI/theme polish): text-only drawable GuiNode. Layout decisions
 * (alignment, offset, font, colour) all live in the resolved TextStyle;
 * the node itself only carries the text payload and the className used
 * by the resolver. No fill / no border — text-only drawables should look
 * like labels, not panels. Alignment is computed against the node's own
 * (w, h) bounds so a text node dropped into a container sizes correctly
 * to its parent. NULL text is treated as an empty string. */
void drawTextGuiNode(void *self) {
	GuiNode *gn = (GuiNode *)self;
	const TextStyle *st = resolveTextStyle(gn);
	Font *lf = styleFont(st->fontName);
	const char *txt = gn->text ? gn->text : "";
	Vector2 m = MeasureTextEx(*lf, txt, (float)st->fontSize, (float)st->spacing);
	float tx = (float)gn->x + st->offsetX;
	float ty = (float)gn->y + st->offsetY;
	if(st->hAlign == TXT_ALIGN_CENTER)      tx += ((float)gn->w - m.x) * 0.5f;
	else if(st->hAlign == TXT_ALIGN_RIGHT)  tx += (float)gn->w - m.x;
	if(st->vAlign == TXT_ALIGN_MIDDLE)      ty += ((float)gn->h - m.y) * 0.5f;
	else if(st->vAlign == TXT_ALIGN_BOTTOM) ty += (float)gn->h - m.y;
	DrawTextEx(*lf, txt, (Vector2){ tx, ty },
	           (float)st->fontSize, (float)st->spacing,
	           gn->selected ? st->colorSelected : st->color);
}

/* Task 3 (UI/theme polish): text-only drawable factory. Non-selectable
 * (so nav skips it), drawable, draw=drawTextGuiNode. text is stored via
 * guiNodeSetText (which handles NULL + strdup); className is stored via
 * guiNodeSetClass (which handles NULL). Returns NULL if createGuiNode
 * rejects the geometry — same failure contract as the other typed
 * factories. */
GuiNode *createTextGuiNode(int x, int y, int w, int h, const char *text, const char *className) {
	GuiNode *gn = createGuiNode(x, y, w, h, 0, na_horizontal, NULL, 0, 0);
	if(gn == NULL) {
		printf("createTextGuiNode error, could not create.");
		return NULL;
	}
	if(className) {
		guiNodeSetClass(gn, className);
	}
	if(text) {
		guiNodeSetText(gn, text);
	}
	gn->drawable = true;
	gn->draw = drawTextGuiNode;
	return gn;
}

/* Task 6: route-destination picker node. Same rect as a dial, but with
 * a brighter outline and the dial's name (strdup'd by cbOpenRouteLayer).
 * Selecting one and EDIT'ing fires cbRouteToDest which toggles the
 * source's route into this destination. */

void drawDiscreteDialGuiNode(void *self) {
	GuiNode *gn = (GuiNode *)self;
	if(!gn->p) {
		return;
	}
	const DialStyle *st = resolveDiscreteDialStyle(gn);
	char paramValue[50];
	snprintf(paramValue, 50, st->value.format, (int)gn->p->baseValue);
	DialGeometry g;
	computeDialGeometry(gn, st, &g);
	/* The graphic can be drawn smaller than its cell: the value and
	 * modulation rings live in the band between graphic and radius. */
	int graphic = st->knob.graphicSize > 0 ? st->knob.graphicSize : st->knob.size;
	if(graphic != st->knob.size && st->knob.size > 0) {
		float k = (float)graphic / (float)st->knob.size;
		g.knobW = (int)((float)g.knobW * k);
		g.knobH = (int)((float)g.knobH * k);
	}

	float angle = 0.0f;
	drawPanelRect(gn->x, gn->y, gn->w, gn->h, st->border.borderWidth, gn->selected,
	               st->border.color, st->border.colorSelected);
	/* The value ring, then the modulation ring behind it, then the knob
	 * graphic inside both. The ring used to be skipped whenever the style
	 * named a knob asset, which left the shipped dial with no value
	 * indication at all. */
	drawDialArcs(gn, st, &g, &angle);
	if(st->knob.hasAsset && st->knob.assetTex.id != 0) {
		DrawTexturePro(st->knob.assetTex, (Rectangle){ 0, 0, st->knob.assetTex.width, st->knob.assetTex.height },
		               (Rectangle){ g.knobX + st->knob.radius + st->knob.offsetX, g.knobY + st->knob.radius + st->knob.offsetY, g.knobW, g.knobH },
		               (Vector2){ g.knobW / 2.0f, g.knobH / 2.0f }, st->knob.startAngle + angle, WHITE);
	} else {
		/* DrawTexturePro places the rotated quad's centre at
		 * (dest.x, dest.y), not at (dest + origin) — so the dest
		 * top-left must carry the +radius offset for the knob graphic
		 * to sit over the arc. knob.offsetX/offsetY nudge it further. */
		DrawTexturePro(dial, (Rectangle){ 0, 0, 48, 48 },
		               (Rectangle){ g.knobX + st->knob.radius + st->knob.offsetX, g.knobY + st->knob.radius + st->knob.offsetY, g.knobW, g.knobH },
		               (Vector2){ st->knob.radius, st->knob.radius }, st->knob.startAngle + angle, WHITE);
	}
	drawValueDisplay(g.valueX, g.valueY, g.valueW, g.valueH, paramValue, st->value.color, st->value.fontSize);
	Font *lf = styleFont(st->label.fontName);
	/* labelX is the label's centre (cell-centred caption); centre the
	 * text on it. */
	float lw = MeasureTextEx(*lf, gn->name, st->label.fontSize, st->label.spacing).x;
	DrawTextEx(*lf, gn->name, (Vector2){ g.labelX - lw * 0.5f, g.labelY }, st->label.fontSize, st->label.spacing,
	           gn->selected ? st->label.colorSelected : st->label.color);
}


void drawWrapperNode(void *self) {
	GuiNode *gn = (GuiNode *)self;
	DrawRectangleRec((Rectangle){ gn->x, gn->y, gn->w, gn->h }, cs.panel);
	DrawRectangleLinesEx((Rectangle){ gn->x, gn->y, gn->w, gn->h }, 2.0, cs.wrapperBorder);
}

/* Task 3: per-instrument chip row. Drawn for each enabled channel above
 * the arranger grid. Bg colour comes from a fixed 8-colour palette keyed
 * by the arranger's per-channel labelColourIdx. Content shows V:{count}
 * top-left, type tag (FM/SMP/BLP) top-right, 8-char channel label
 * centred, current patch name bottom-left, and a voice-active light
 * bottom-right per voice in vm->voiceCount[ch].
 *
 * IMPORTANT: this MUST early-return when vm or inst is NULL — the nav
 * test in tests/dsp/test_graph_nav.c builds chips with NULL refs so it
 * can exercise the graph layout (chipRow RIGHT/DOWN navigation) without
 * needing a real VoiceManager or Instrument. */

const char *voiceTypeTag(VoiceType t) {
	switch(t) {
		case VOICE_TYPE_FM:     return "FM";
		case VOICE_TYPE_BLEP:   return "BLP";
		case VOICE_TYPE_GRAIN:  return "GRN";
		case VOICE_TYPE_SPECTRAL: return "SPC";
		case VOICE_TYPE_SAMPLE:
		default:                return "SMP";
	}
}


bool isSelectedDialNode(const Graph *g) {
	if(!g || !g->selected) return false;
	GuiNode *n = g->selected;
	/* Both continuous (drawDialGuiNode) and discrete (drawDiscreteDialGuiNode)
	 * dials expose a value-callback OnPressCallback and respond to EDIT+arrow.
	 * Some discrete dials (e.g. ROUTE) overwrite draw with the discrete variant
	 * after createDialGuiNode; both must pass the guard so the harness can
	 * drive them via the scripted EDIT<arrow> opcodes. */
	return (n->draw == drawDialGuiNode || n->draw == drawDiscreteDialGuiNode)
		&& n->callback != NULL;
}


void DrawGUI(int currentScene) {
	switch (currentScene) {
		case SCENE_ARRANGER:
			gui_arranger_draw();
			break;
		case SCENE_PATTERN:
			gui_pattern_draw();
			break;
		case SCENE_INSTRUMENT:
			gui_instrument_draw();
			break;
		default:
			break;
	}
}
